SELECT 
FROM TBL_TREASURY_BUSINESS_RULES


        AND RULE_CODE LIKE CONCAT('%', #{ruleCode}, '%')


        AND RULE_NAME LIKE CONCAT('%', #{ruleName}, '%')


        AND RULE_TYPE = #{ruleType}


        AND BUSINESS_MODULE = #{businessModule}


        AND BUSINESS_DEFINITION_ID = #{businessDefinitionId}


        AND IS_ENABLED = #{isEnabled}


        AND ORG_ID = #{orgId}


ORDER BY PRIORITY ASC, CREATE_TIME DESC

SELECT COUNT(1)
FROM TBL_TREASURY_BUSINESS_RULES
WHERE RULE_CODE = #{ruleCode} AND ORG_ID = #{orgId}

    AND RULE_ID != #{excludeId}

SELECT 
FROM TBL_TREASURY_BUSINESS_RULES
WHERE RULE_TYPE = #{ruleType}
  AND BUSINESS_MODULE = #{businessModule}
  AND ORG_ID = #{orgId}
ORDER BY PRIORITY ASC, RULE_CODE
